const body = $input.item.json.body;
let message = body.message || '';
const to = body.to || 'YOUR_PHONE_NUMBER';

// SMS-friendly formatting: strip markdown
message = message
  .replace(/\*\*(.*?)\*\*/g, '$1')  // bold
  .replace(/\*(.*?)\*/g, '$1')      // italic
  .replace(/`(.*?)`/g, '$1')        // code
  .replace(/\n{3,}/g, '\n\n');      // excessive newlines

// Cap at 1600 chars (Twilio max per message)
if (message.length > 1600) {
  message = message.substring(0, 1597) + '...';
}

return [{ json: { message, to } }];
